<?php $variantsCard=$p['variants'];$v=$variantsCard[0]??null; ?>
<article class="product-card"><a class="product-photo" href="<?= e(url('product',['slug'=>$p['slug']])) ?>"><img src="<?= e(asset($p['image'])) ?>" alt="<?= e($p['name']) ?>" loading="lazy"><?php if($p['featured']): ?><span class="product-badge">PANTRY FAVOURITE</span><?php endif ?><?php if($v && $v['compare_price']>$v['price']): ?><span class="sale-badge"><?= round((1-$v['price']/$v['compare_price'])*100) ?>% OFF</span><?php endif ?></a><div class="product-body"><div class="product-meta"><?= e($p['category_name']??'THE PICKLE PANTRY') ?><?php if(!empty($p['review_count'])): ?><span>★ <?= number_format($p['rating'],1) ?> (<?= (int)$p['review_count'] ?>)</span><?php endif ?></div><h3><a href="<?= e(url('product',['slug'=>$p['slug']])) ?>"><?= e($p['name']) ?></a></h3><p><?= e($p['short_description']) ?></p><?php if($v): ?><form class="add-cart-form" action="<?= e(url('cart/add')) ?>" method="post"><?= csrf() ?><input type="hidden" name="quantity" value="1"><div class="product-price-row"><span class="price" data-price><?= money($v['price']) ?></span><select class="variant-select" name="variant_id" aria-label="Pack size for <?= e($p['name']) ?>"><?php foreach($variantsCard as $option): ?><option value="<?= $option['id'] ?>" data-price="<?= $option['price'] ?>" data-stock="<?= $option['stock'] ?>"><?= e($option['label']) ?><?= !$option['stock']?' · Sold out':'' ?></option><?php endforeach ?></select></div><button class="btn btn-outline-primary w-100 add-button" <?= !$v['stock']?'disabled':'' ?>><?= $v['stock']?'Add to bag　+':'Sold out' ?></button></form><?php else: ?><p class="muted">Packs coming soon</p><?php endif ?></div></article>
